update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p086","body":"خبر خزاں کے آنے کی لائے تھے\nبہار آئی تھی کہ تم آئے تھے؟\n\nپوچھتے ہیں پروانے سے کہ کیوں آئے تھے\nجہاں آتش گل دکھی سو کھچے آئے تھے\n\nعمر گزری سکوں کی تلاش میں\nعمر بھر کانٹوں بھرے سائے تھے\n\nتیری فرقت کے دنوں میں یہی مشغلہ اپنا تھا\nتیرے فراق میں بار بار وہی خواب دھرائے تھے\n\nیہ بھی نہیں کہ وہ رہے سدا برہم احمد\nکبھی دیکھ کر ہمیں وہ بھی تو مسکرائے تھے"},{"slug":"tum-p087","body":"کبھی جاگتے ہیں تو اکثر سو جاتے ہیں\nتجھے بھولنے بھلانے میں ترے ہو جاتے ہیں\n\nمنزل کی تاک میں رہنے والے ، زندگی\nسفر کی جستجو میں سو جاتے ہیں\n\nجن پتھروں پہ گریں بوند بوند رنجشیں\nآخر وہ پتھر بھی دم ہار کے رو جاتے ہیں\n\nلوگ اکثر لفظوں کے تعقب کی دلیلوں سے\nلہجوں کی سختیوں کو دھو جاتے ہیں\n\nاحمد ؔ کبھی کبھی زندگی سے اکتائے ہم\nسراسر ترے خیالوں میں  کھو جاتے ہیں"},{"slug":"tum-p088","body":"ایک جگنو کمرے میں آئے اور دیپ جلائے\nآج ایک دن اور گزر گیا پر تم نہیں آئے\n\nآوارگی ، بے دلی ، بد حواسی ہے اس قدر\nرات کی تاریکی میں کوئی گھر سے باہر جائے\n\nہم سے مصلحتاً کچھ تو ہوا ہوگا جس کے سبب\nجو نہ کوئی بھائے ، نہ دل لگائے ، نہ پاس بلائے\n\nہر شخص کی نظروں کا ازل سے مرکز تھا تو\nیوں ہم نے کچی عمر سے تھے بہت گل کھلائے\n\nدو چار دوست ہیں محض عادت سے میری آشنا\nسب سے ہی فقط عادتا ہم نے بہت دھوکے کھائے\n\nاب وقت کہاں فارغ فرصت بھری زندگی میں\nاحمد ؔ  بہت ضروری کام سے آج مجھے تم یاد آئے"},{"slug":"tum-p089","body":"کبھی دل اداس رہا کبھی اسے شاد کیا\nتمہیں آج کے دن میں نے بہت یاد کیا\n\nآپ سے شکوہ بھی کیا کریں\nخیر آپ نے ہی برباد کیا\n\nافسانوں بھری خواہشیں تھیں\nزندگی نے جنھیں خیرباد کیا\n\nاس ستم گری سے اور کچھ تو نہیں ملا\nبس جو دکھ ملے مجھے انہی کو روداد کیا\n\nنہ آنکھوں کو بھایا کوئی ، نہ دل نے تصدیق کی\nاحمد ؔ ہم نے بہت چاہا اور بہت تضاد کیا"},{"slug":"tum-p090","body":"یوں فلک پہ بے انتہا ستارے ہیں\nایک ہم ہیں کہ صرف تمہارے ہیں\nکئی خواب ہیں میرے تم سے وابستہ\nکئی تعبیروں میں تمہارے اشارے ہیں\n\nخوابوں میں ایک چنچل سی افسردہ لڑکی ہے\nتعبیروں میں جو کہ فقط تم جیسی ہے\nآنکھوں میں جس کی خواب سنہرے ہیں\nاور پس آئینہ اشکوں کے ڈیرے ہیں\nلبوں پہ جس کے دوستی کے نغمے ہیں\nمحفل میں جس کی کہنے کو سبھی اپنے ہیں\nوہ لڑکی جو دور سے ہی چمکتی نظر آتی تھی\nوہی لڑکی اب ستاروں کے اردگرد کیوں مدہم ہے\nہونٹوں پہ جس کی ہر دم وفا کے نغمے ہوا کرتے تھے\nچہرے سے وہ اس قدر آخر کیوں برہم ہے\n\nسنو! اس کا سبب جو بھی کوئی غم ہے\nاسکا مول تمہاری ہنسی سے بہت کم ہے\nستاروں سے بھرے آسماں میں\nسب سے بڑھ کر جگمگاتی رہو\nتم خواب سجاتی رہو\nیونہی ہاں یونہی مسکراتی رہو"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
